/// <summary>One Argon2id case: inputs in hex (empty: none), parameters and the expected tag.</summary>
public sealed record Argon2Case(string Password, string Salt, string Secret, string Data, int TimeCost, int MemoryKiB, int Lanes,
    int TagLength, string Tag)
{
    public override string ToString() => $"t={TimeCost} m={MemoryKiB} p={Lanes} T={TagLength} password={Password.Length / 2}B salt={Salt.Length / 2}B";
}

